/**
 * Renders the generated index of settings contributions from the contributor file names
 * (`a19.tsx`, `a30.tsx`, ...), sorted, each imported under its own identifier.
 */
export function renderContributionsIndex(fileNames: readonly string[]): string {
  const modules = fileNames
    .filter((f) => /^[a-z][a-z0-9-]*\.tsx$/.test(f))
    .map((f) => f.slice(0, -".tsx".length))
    .sort();
  const ident = (m: string) => `from_${m.replaceAll("-", "_")}`;
  return [
    "// Generated by apps/atlas/test/settings-contributions.test.ts (XOS_WRITE_GENERATED=1) from the contributor files here.",
    "// Never edit by hand; on a merge conflict, take either side and rerun the generator.",
    'import type { SettingsContribution } from "./types";',
    ...modules.map((m) => `import { contributions as ${ident(m)} } from "./${m}";`),
    "",
    "export const CONTRIBUTIONS: readonly SettingsContribution[] = [",
    ...modules.map((m) => `  ...${ident(m)},`),
    "];",
    "",
  ].join("\n");
}
